'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const { createLimiter } = require('./src/limit');

test('validates concurrency and rejects non-functions without consuming a slot', async () => {
  for (const value of [0, -1, 1.5, NaN, Infinity, '2', null, undefined, 2n]) {
    assert.throws(() => createLimiter(value), RangeError);
  }
  const run = createLimiter(1);
  for (const value of [null, undefined, 42, {}]) {
    const result = run(value);
    assert.ok(result instanceof Promise);
    await assert.rejects(result, TypeError);
  }
  assert.equal(await run(() => 42), 42);
});

test('invokes each task once, without arguments, and recovers from throws and rejections', { timeout: 2000 }, async () => {
  const run = createLimiter(1);
  const error = new Error('expected');
  const started = [];
  const tasks = [
    function () { throw error; },
    function () { return Promise.reject(error); },
    function () { return 42; },
    function () { return Promise.resolve(43); }
  ];
  const results = tasks.map((fn, index) => run(function () {
    assert.equal(arguments.length, 0);
    assert.equal(this, undefined);
    started.push(index);
    return fn();
  }));
  const settled = await Promise.allSettled(results);
  assert.deepEqual(started, [0, 1, 2, 3]);
  assert.deepEqual(settled, [
    { status: 'rejected', reason: error },
    { status: 'rejected', reason: error },
    { status: 'fulfilled', value: 42 },
    { status: 'fulfilled', value: 43 }
  ]);
  assert.equal(await run(() => 'still usable'), 'still usable');
});
